{
  "pairs": [
    {
      "topic": "道路渋滞の経済・時間・環境損失の現状",
      "question": {
        "summary": "- 現在の交通渋滞による経済損失、時間損失、環境負荷の具体的な数値を教えてほしい\n- 渋滞がもたらす労働時間のロスやCO₂排出量の規模を知りたい\n- GDPへの影響についても把握できる情報があれば提示してほしい",
        "sentence_indices": [4,5,6,7,8,9,10,11,12],
        "intent": "information_request"
      },
      "answer": {
        "summary": "- 渋滞による時間ロスは年間約61億人時間、労働時間に換算すると約370万人分\n- CO₂排出量は全国総排出量の約1.3%に相当すると試算\n- 首都高速中央環状線全線開通で年間約8,200億円の経済効果があった事例を示し、ハード・ソフト対策で緩和を図る方針",
        "sentence_indices": [15,16,17,18,19,20]
      }
    },
    {
      "topic": "ETC2.0の概要と導入状況",
      "question": {
        "summary": "- 従来のETCとETC2.0の違いを説明してほしい\n- 現在のETC2.0の普及率や導入台数を教えてほしい\n- データ活用の方針や具体的な利用例について知りたい",
        "sentence_indices": [27,28,29,30],
        "intent": "information_request"
      },
      "answer": {
        "summary": "- ETC2.0は料金収集に加え情報提供や走行履歴データ収集機能を持つ\n- 累計約1,500万台が搭載され、利用者の約4割がETC2.0利用者\n- 渋滞情報や路面状況の提供、災害時のトラベルマップ作成などに活用している",
        "sentence_indices": [33,34,35,36]
      }
    },
    {
      "topic": "ETC2.0搭載車種別と利用者への便益",
      "question": {
        "summary": "- ETC2.0が搭載されている大型車・普通車の台数を教えてほしい\n- ETC2.0が道路利用者にもたらす具体的な便益を説明してほしい",
        "sentence_indices": [38,39,40],
        "intent": "information_request"
      },
      "answer": {
        "summary": "- 大型車は約609万台、普通車は約200万台がETC2.0搭載\n- 渋滞情報の把握でルート選択が可能になり、料金所渋滞が解消されるなどの利便性が向上",
        "sentence_indices": [43,44,45,46]
      }
    },
    {
      "topic": "ETC2.0と従来ETCの利用者メリット比較",
      "question": {
        "summary": "- ETC2.0が従来ETCに比べて利用者に提供するメリットを具体的に示してほしい\n- 例えば割引や経路情報活用など、利用者側の利点を教えてほしい",
        "sentence_indices": [47,48,49],
        "intent": "information_request"
      },
      "answer": {
        "summary": "- ETC2.0は走行経路が把握でき、環状道路利用時の割引適用が可能\n- 走行経路情報に基づくサービス提供がETCにはない新たなメリット",
        "sentence_indices": [52,53]
      }
    },
    {
      "topic": "ETC2.0普及促進策についての政府方針",
      "question": {
        "summary": "- ETC2.0の普及を進めるための具体的な施策や方針を教えてほしい\n- 補助金や価格差是正など、普及促進に向けた取り組みを知りたい",
        "sentence_indices": [59,60,61],
        "intent": "policy_proposal"
      },
      "answer": {
        "summary": "- ETC2.0の普及促進として、車載機購入助成や広報活動を実施\n- 価格差は約1万円から2万円であるため、助成で縮小し利用者メリットを訴求\n- 今後も投資を行い、データ活用による施策展開を加速させる方針",
        "sentence_indices": [62,63,64,65,66,67,68,69,70,71,72,73,74,75,76,77,78,79,80,81]
      }
    },
    {
      "topic": "北海道等の積雪地域におけるポットホール対策",
      "question": {
        "summary": "- 雪解け時に発生するポットホール等の道路損傷への対策を教えてほしい\n- 現在の補修支援や予防保全の取り組みについて説明してほしい",
        "sentence_indices": [92,93,94,95],
        "intent": "policy_proposal"
      },
      "answer": {
        "summary": "- 防災安全交付金や地方債で補修支援を実施\n- 予防保全として新技術開発・試験施工を進め、長寿命化技術の公募を行っている\n- 今後も技術普及促進とモニタリングで道路舗装の保全を強化する方針",
        "sentence_indices": [96,97,98,99,100,101,102,103]
      }
    },
    {
      "topic": "国内航空路線事業の現状",
      "question": {
        "summary": "- 国内線事業の現在の経営状況と課題を説明してほしい\n- 需要回復や収支の実態について具体的に知りたい",
        "sentence_indices": [108,109,110,111],
        "intent": "information_request"
      },
      "answer": {
        "summary": "- 燃料費・整備費の増大やコロナ後の需要変化で収益確保が困難\n- 有識者会議で構造改革策を検討中で、国内航空ネットワーク維持に取り組む方針",
        "sentence_indices": [112,113,114,115]
      }
    },
    {
      "topic": "航空機燃料税の見直し",
      "question": {
        "summary": "- 航空機燃料税の現行制度と課税目的の達成状況を説明してほしい\n- 税の恒久化や段階的削減など、見直し案について提案してほしい",
        "sentence_indices": [117,118,119,120],
        "intent": "policy_proposal"
      },
      "answer": {
        "summary": "- 燃料税は空港整備・防災対策の財源で重要\n- 現行の軽減措置は継続しつつ、関係者の意見を踏まえて議論を進める方針",
        "sentence_indices": [121,122,123,124,125]
      }
    },
    {
      "topic": "空港グラウンドハンドリングの労働環境改革",
      "question": {
        "summary": "- グラウンドハンドリング従事者の人材確保・賃金・労働環境改善策を教えてほしい\n- DX化や制度改革による業務効率化の取り組みについて説明してほしい",
        "sentence_indices": [126,127,128,129,130,131,132],
        "intent": "policy_proposal"
      },
      "answer": {
        "summary": "- 人材確保・育成・処遇改善とDX化で受入体制を強化\n- 国際観光旅客税や特定技能制度で費用支援、取引適正化を実施\n- 空港内自動運転車や自動ボーディングブリッジ等の新技術導入を推進",
        "sentence_indices": [133,134,135,136,137,138,139,140,141,142]
      }
    }
  ]
}
